var scene = UnityEditor.SceneManagement.EditorSceneManager.OpenScene("Assets/Project/GameLobby.unity", UnityEditor.SceneManagement.OpenSceneMode.Single);
var roots = scene.GetRootGameObjects();
var sb = new System.Text.StringBuilder();
sb.AppendLine($"Scene: {scene.name}");
foreach (var root in roots) {
    sb.AppendLine($"- {root.name} ({root.GetComponents<Component>().Length} comps)");
    foreach (Transform child in root.transform) {
        sb.AppendLine($"  -- {child.name} ({child.GetComponents<Component>().Length} comps)");
        foreach (Transform grand in child) {
            sb.AppendLine($"    --- {grand.name} ({grand.GetComponents<Component>().Length} comps)");
        }
    }
}
return sb.ToString();
